        expect(IllegalStateException.class, () -> d.escalate(1), "fails");
        eq(list("0: opened p3", "1: escalated to p2", "1: escalated to p1"), d.history(1), "log");
    }

    static void testTagsAreLogged() {
        Desk d = desk();
        d.tag(2, "vpn");
        d.tag(2, "vpn");
