    }

    static void testBreached() {
        Desk d = desk();
        eq(ints(), ids(d.breached()), "nothing at the start");
        for (int i = 0; i < 2; i++) {
            d.tick();
        }
        eq(ints(), ids(d.breached()), "exactly at the deadline is not breached");
        d.tick();
        eq(ints(4), ids(d.breached()), "one tick later the p1 ticket is");
