        d.merge(1, 3);
        expect(IllegalStateException.class, () -> d.reopen(3), "merged away");
        check(d.get(3).closed(), "still closed");
        d.close(2);
        d.reopen(2);
    }

    static void testBulkCloseIsLogged() {
