        note(id, "assigned to " + t.agent());
        return t;
    }

    public int workload(String agent) {
        int n = 0;
        for (Ticket t : tickets.values()) {
            if (!t.closed() && agent != null && agent.equals(t.agent())) {
                n++;
            }
        }
        return n;
