        this.id = id;
        this.subject = subject;
        this.priority = priority;
        this.openedAt = openedAt;
    }

    public int id() {
        return id;
    }

    public String subject() {
        return subject;
    }

    public int priority() {
        return priority;
    }

    public int openedAt() {
