        List<Ticket> out = new ArrayList<>();
        for (Ticket t : tickets.values()) {
            if (!t.closed()) {
                out.add(t);
            }
        }
        out.sort(Comparator.comparingInt(Ticket::priority).thenComparingInt(Ticket::id));
        return out;
    }

    public Optional<Ticket> next() {
        return openTickets().stream().findFirst();
    }

