            if (!type.isInstance(t)) {
                failures++;
                System.out.println("FAIL: " + msg + ": threw " + t);
            }
            return;
        }
        failures++;
        System.out.println("FAIL: " + msg + ": no exception");
    }

    /** Four tickets: 1 printer (p3), 2 login (p2), 3 wifi (p3), 4 server (p1), all opened at tick 0. */
    static Desk desk() {
        Desk d = new Desk();
