        for (Ticket t : ts) {
            out.add(t.id());
        }
        return out;
    }

    static List<Integer> ints(Integer... xs) {
        return new ArrayList<>(Arrays.asList(xs));
    }

    static List<String> list(String... xs) {
        return new ArrayList<>(Arrays.asList(xs));
    }


