        if (tag == null || !tag.matches("[a-z0-9][a-z0-9-]{0,23}")) {
            throw new IllegalArgumentException("bad tag: " + tag);
        }
        boolean added = t.addTag(tag);
        if (added) {
            note(id, "tagged " + tag);
        }
        return added;
    }

    public boolean untag(int id, String tag) {
        Ticket t = get(id);
        boolean removed = t.removeTag(tag);
        if (removed) {
            note(id, "untagged " + tag);
        }
        return removed;
    }

    public List<Ticket> withTag(String tag) {
        List<Ticket> out = new ArrayList<>();
        for (Ticket t : tickets.values()) {
            if (t.tags().contains(tag)) {
                out.add(t);
            }
        }
        return out;
    }

    public static int slaTicks(int priority) {
        switch (priority) {
            case 1:
                return 4;
            case 2:
                return 8;
            case 3:
                return 12;
            case 4:
                return 24;
            default:
                throw new IllegalArgumentException("priority must be 1 to 4");
