package queuedesk;

import java.util.*;

/** One help-desk ticket. */
public final class Ticket {
    private final int id;
    private final String subject;
    private int priority;
    private final int openedAt;
    private boolean closed;
    private String agent;
    private final TreeSet<String> tags = new TreeSet<>();
    private Integer mergedInto;

    Ticket(int id, String subject, int priority, int openedAt) {
        this.id = id;
        this.subject = subject;
        this.priority = priority;
        this.openedAt = openedAt;
    }

    public int id() {
        return id;
    }

    public String subject() {
        return subject;
    }

    public int priority() {
        return priority;
    }

    public int openedAt() {
        return openedAt;
    }

    public boolean closed() {
        return closed;
    }

    void setPriority(int priority) {
        this.priority = priority;
    }

    void setClosed(boolean closed) {
        this.closed = closed;
    }

    public String agent() {
        return agent;
    }

    void setAgent(String agent) {
        this.agent = agent;
    }

    public List<String> tags() {
        return new ArrayList<>(tags);
    }

    boolean addTag(String tag) {
        return tags.add(tag);
    }

    boolean removeTag(String tag) {
        return tags.remove(tag);
    }

    public Integer mergedInto() {
        return mergedInto;
    }

    void setMergedInto(Integer id) {
        this.mergedInto = id;
    }
}

